            prv = m
        else:
            dec = int(left) - 1
            ds = str(dec)
            if dec <= 0 or len(ds) < h:
                prv = 10 ** (L - 1) - 1
            else:
                prv = mirror(ds)
        return (n - prv) < (nxt - n)
    except Exception:
        return False

